   if(array_key_exists('searxng_url',$in))$s['search']['searxng_url']=trim((string)$in['searxng_url']);if(array_key_exists('ollama_web_key',$in))$s['search']['ollama_web_key']=trim((string)$in['ollama_web_key']);if(array_key_exists('ai_enrich',$in))$s['search']['ai_enrich']=(bool)$in['ai_enrich'];if(array_key_exists('image_provider',$in))$s['images']['provider']=(string)$in['image_provider'];if(array_key_exists('sdwebui_url',$in))$s['images']['sdwebui_url']=trim((string)$in['sdwebui_url']);if(array_key_exists('pollinations_model',$in))$s['images']['pollinations_model']=trim((string)$in['pollinations_model']);if(array_key_exists('system_prompt',$in))$s['system_prompt']=trim((string)$in['system_prompt']);
