   aih_save_settings($s);aih_audit('settings_saved');aih_json(['ok'=>true]);
 }
 aih_json(['ok'=>false,'error'=>'Unknown action'],404);
} catch(Throwable $e){aih_json(['ok'=>false,'error'=>'Server error: '.$e->getMessage()],500);}
